# Mutacoes da gravacao dos .dat: cada uma muda um campo (nao id, chave nem ponteiro) de todos os registros
# antes de gravar; a tabela gravada vai para o .qst da prova do save, que acusa pelos bytes.
MUTACOES = [
    ('dbg_nao_jogadores', '    crate::comparison::branch("database write non-players");', '    crate::comparison::branch("database write non-players");\n    for i in 0..n as usize { let r = registros + i * 68; *((r + 0x10) as *mut u8) = (*((r + 0x10) as *const u8)).wrapping_add(1); } // mutacao: o treino (coaching, +0x10) + 1 (fica na memória também; não é id, chave nem ponteiro)'),
    ('dbg_jogadores', '    crate::comparison::branch("database write players");', '    crate::comparison::branch("database write players");\n    for i in 0..n as usize { let r = registros + i * 70; *((r + 0x11) as *mut u8) = (*((r + 0x11) as *const u8)).wrapping_add(1); } // mutacao: a posição de zagueiro (+0x11) + 1 (fica na memória também; não é id, chave nem ponteiro)'),
    ('dbg_preferencias', '    crate::comparison::branch("database write preferences");', '    crate::comparison::branch("database write preferences");\n    for i in 0..n as usize { let r = registros + i * 52; let a = (r + 0x4) as *mut i32; let b = (r + 0x8) as *mut i32; let t = a.read_unaligned(); a.write_unaligned(b.read_unaligned()); b.write_unaligned(t); } // mutacao: o 1º e o 2º clube favorito (+0x4, +0x8) trocados (fica na memória também; não é id, chave nem ponteiro)'),
]
